FraAttr = FRA
    L3Mdev -> L3MDEV
    Sport -> SPORT_RANGE
    Dport -> DPORT_RANGE
FibRuleAction = FR_ACT
NdaAttr = NDA
    Flags -> FLAGS_EXT
NeighborState = NUD
OperState = IF_OPER
