NatType = NFT_NAT
RangeOp = NFT_RANGE
PktType = PACKET
    OtherHost -> OTHERHOST
FibResult = NFT_FIB_RESULT
    OifName -> OIFNAME
    AddrType -> ADDRTYPE
LimitKind = NFT_LIMIT
    Packets -> PKTS
    Bytes -> PKT_BYTES
IcmpxCode = NFT_REJECT_ICMPX
    NoRoute -> NO_ROUTE
    PortUnreachable -> PORT_UNREACH
    HostUnreachable -> HOST_UNREACH
